<script>
(() => { const value = @json($registration->public_registration_code), patterns = {'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn','K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn','U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn','-':'nwnnnnwnw','*':'nwnnwnwnn'}; const svg=document.getElementById('registration-barcode'), data='*'+value+'*'; let units=0; for(const ch of data) for(const w of patterns[ch]) units+=w==='w'?3:1; units+=data.length-1; const scale=Math.max(1, Math.floor(500/units)); let x=0, bars=''; for(const ch of data){ [...patterns[ch]].forEach((w,i)=>{const width=(w==='w'?3:1)*scale;if(i%2===0)bars+=`<rect x="${x}" y="0" width="${width}" height="110"/>`;x+=width});x+=scale} svg.setAttribute('viewBox',`0 0 ${x} 110`); svg.setAttribute('width',x); svg.setAttribute('height','110'); svg.innerHTML=bars; })();
</script>
